            var html = '<div class="card-crown"></div><div class="card-header"><div class="header-icon">⬡</div><div class="header-info"><div class="item-name">' + name + '</div><div class="item-sub">' + (data['类别'] || '消耗品') + ' · ' + (data['来源'] || '未知') + '</div></div><div class="rarity-badge">' + (data['品阶'] || '普通') + '</div></div>' + renderDivider() + '<div class="card-body">';
            if (data['使用条件']) html += '<div class="section"><span class="cost-tag">' + data['使用条件'] + '</span></div>';
            if (data['效果']) html += '<div class="section"><div class="section-title">✦ 药理效果 ✦</div>' + renderEffects(data['效果']) + '</div>';
            html += '</div><div class="card-footer"><span class="footer-price">◈ ' + (data['价格'] || '—') + '</span><span class="footer-weight">堆叠: ' + (data['堆叠'] || '否') + '</span></div>';
            if (data['描述']) html += '<div class="card-lore">' + data['描述'] + '</div>';
            return html;
        }

        function renderMaterial(data) {
            var name = data['名称'] || '未知材料';
            var html = '<div class="card-crown"></div><div class="card-header"><div class="header-icon">◇</div><div class="header-info"><div class="item-name">' + name + '</div><div class="item-sub">' + (data['类别'] || '材料') + ' · ' + (data['来源'] || '未知') + '</div></div><div class="rarity-badge">' + (data['品阶'] || '普通') + '</div></div>' + renderDivider() + '<div class="card-body"><div class="section">' + renderField('用途', data['用途']) + renderField('DC修正', data['DC修正']) + '</div></div><div class="card-footer"><span class="footer-price">◈ ' + (data['价格'] || '—') + '</span><span class="footer-weight">堆叠: ' + (data['堆叠'] || '是') + '</span></div>';
            if (data['描述']) html += '<div class="card-lore">' + data['描述'] + '</div>';
            return html;
        }

        function renderQuest(data) {
            var rank = data['等级'] || 'D';
            var name = data['名称'] || '未知任务';
            var html = '<div class="card-crown"></div><div class="card-header"><div class="quest-rank rank-' + rank + '">' + rank + '</div><div class="header-info"><div class="item-name">' + name + '</div><div class="item-sub">' + (data['类别'] || '任务') + ' · ' + (data['发布方'] || '未知') + '</div></div><div class="rarity-badge" style="border-color:#a39c91;color:#6b6357;">' + (data['当前状态'] || '进行中') + '</div></div>' + renderDivider() + '<div class="card-body">';
            if (data['报酬']) { html += '<div class="section"><div class="section-title">✦ 悬赏报酬 ✦</div>'; Object.keys(data['报酬']).forEach(function(k) { if(data['报酬'][k] && data['报酬'][k]!=='无') html += renderField(k, data['报酬'][k]); }); html += '</div>'; }
            if (data['目标']) { html += '<div class="section"><div class="section-title">✦ 委托目标 ✦</div>'; data['目标'].forEach(function(obj) { if(typeof obj === 'string') { var statusCls = 'obj-active'; var textCls = ''; if(obj.indexOf('完成')>=0) { statusCls = 'obj-done'; textCls = 'done'; } else if(obj.indexOf('未解锁')>=0) { statusCls = 'obj-locked'; textCls = 'locked'; } html += '<div class="quest-obj"><div class="obj-dot ' + statusCls + '"></div><span class="obj-text ' + textCls + '">' + obj + '</span></div>'; } }); html += '</div>'; }
            if (data['备注']) html += '<div class="section"><div class="section-title">✦ 委托备注 ✦</div><div class="field-row"><span class="field-value" style="color:#7a6a50;font-size:12.5px;">' + data['备注'] + '</span></div></div>';
            html += '</div><div class="card-footer"><span class="footer-weight">编号: ' + (data['编号'] || '—') + '</span><span class="footer-weight">期限: ' + (data['期限'] || '无期限') + '</span></div>';
            return html;
        }

        function renderCard(data) {
            var type = data._type || '';
            var rarity = getRarityBase(data['品阶'] || '普通');
            var html = '';

            switch(type) {
                case '技能': html = renderSkill(data); break;
                case '武器': html = renderEquipment(data, '武器'); break;
                case '防具': html = renderEquipment(data, '防具'); break;
                case '饰品': html = renderEquipment(data, '饰品'); break;
                case '消耗品': html = renderConsumable(data); break;
                case '材料': html = renderMaterial(data); break;
                case '任务': html = renderQuest(data); rarity = '稀有'; break;
                case '加护与权能': html = renderBlessing(data); break;
                case '物品': html = renderItem(data); break;
                default: return '<div class="error">❌ 未识别的古卷: ' + type + '</div>';
            }

            return '<div class="game-card rarity-' + rarity + '">' + html + '</div>';
        }

        function init() {
            try {
                var rawEl = document.getElementById('raw-data');
                if (!rawEl) { document.getElementById('game-panel').innerHTML = '<div class="error">❌ 契约文书未找到</div>'; return; }
                var rawText = rawEl.textContent || rawEl.innerText || '';
                if (!rawText.trim()) { document.getElementById('game-panel').innerHTML = '<div class="error">❌ 契约文书空白</div>'; return; }
                var data = parseSimpleYaml(rawText);
                if (!data || !data._type) { document.getElementById('game-panel').innerHTML = '<div class="error">❌ 无法解译古卷文字</div>'; return; }
                document.getElementById('game-panel').innerHTML = renderCard(data);
            } catch(error) {
                document.getElementById('game-panel').innerHTML = '<div class="error">❌ ' + error.message + '</div>';
            }
        }

        $(function() { init(); });
    </script>
